// n8n's Gmail node cannot set mail headers, so the email is built here and sent
// through the Gmail API. The app's headers keep a client's weekly reports in one thread.
const email = $('Report Email Webhook').first().json.body.email;
const from = $input.first().json.emailAddress;
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
// One line per header, and anything outside plain ASCII encoded so mail apps read it.
const header = (v) => {
  const s = String(v).replace(/[\r\n]+/g, ' ');
  return /^[\x20-\x7e]*$/.test(s) ? s : `=?UTF-8?B?${b64(s)}?=`;
};
const lines = [
  `From: SavyTime <${from}>`,
  `To: ${header(email.to)}`,
  `Subject: ${header(email.subject)}`,
  ...Object.entries(email.headers || {}).map(
    ([name, value]) => `${name.replace(/[^A-Za-z-]/g, '')}: ${header(value)}`,
  ),
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(email.html).replace(/.{76}/g, '$&\r\n'),
];
return [{ json: { raw: Buffer.from(lines.join('\r\n'), 'utf8').toString('base64url') } }];
